package com.portfolio.financeflow.controller;import com.portfolio.financeflow.model.Budget;import com.portfolio.financeflow.repo.BudgetRepository;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/budgets") @CrossOrigin(origins="http://localhost:5173")public class BudgetController{final BudgetRepository r;BudgetController(BudgetRepository r){this.r=r;}@GetMapping List<Budget>all(){return r.findAll();}@PostMapping ResponseEntity<Budget>create(@Valid @RequestBody Budget b){return ResponseEntity.status(HttpStatus.CREATED).body(r.save(b));}}
